package com.cenedu.backend.ai.problem.render;
import static org.assertj.core.api.Assertions.*; import com.cenedu.backend.ai.problem.adapter.SafeSvgSanitizer; import com.cenedu.backend.domain.problem.authoring.diagram.*; import java.util.*; import org.junit.jupiter.api.Test;
class DiagramFamilyRendererTest { private final DiagramViewport v=new DiagramViewport(640,240,16); private final DiagramStyle s=new DiagramStyle("#000000","#FFFFFF","#FF0000",1,"sans-serif",12); private final ProblemDiagramRenderer r=new ProblemDiagramRenderer(new SafeSvgSanitizer()); @Test void rendersAllFamiliesDeterministically(){List<DiagramSpecV1> ds=List.of(new NumberLineDiagramSpecV1(1,"N",DiagramKind.NUMBER_LINE,v,s,"A","B","C",List.of(),List.of(),false,false),new CoordinateGraphDiagramSpecV1(1,"C",DiagramKind.COORDINATE_GRAPH,v,s,"A","B","C","D","E","F",List.of(),List.of(),List.of(),List.of()),new PlaneGeometryDiagramSpecV1(1,"P",DiagramKind.PLANE_GEOMETRY,v,s,List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of()),new SolidGeometryDiagramSpecV1(1,"S",DiagramKind.SOLID_GEOMETRY,v,s,SolidGeometryKind.PRISM,null,null,null,null,null,null,List.of()),new DataTableDiagramSpecV1(1,"T",DiagramKind.DATA_TABLE,v,s,List.of("r"),List.of("c"),List.of(),Set.of()));for(var d:ds){var a=r.render(d,new DiagramRenderContext(Map.of()));var b=r.render(d,new DiagramRenderContext(Map.of()));assertThat(a.svg()).isEqualTo(b.svg()).contains("viewBox");assertThat(a.sha256()).isEqualTo(b.sha256());}} }
